    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 37 (13 marks) Cerebrospinal fluid (CSF) is a clear fluid that surrounds the brain and spinal cord. It contains mostly water, glucose, urea and some salts. One function of the CSF is to act as a shock absorber to protect the brain from any physical or mechanical damage. In addition to the function of the CSF in protecting the brain and spinal cord, name two other functions of this fluid. (2 marks) Name two other structures that protect the brain from damage.(2 marks) Daryl was an avid motorcyclist who lived in the far north of Western Australia and would sometimes forgo protective equipment, including his helmet, due to the extreme temperatures. One day he was riding his motorbike, fell and hit his head causing damage to his cerebellum. Suggest two symptoms Daryl could have suffered after his accident that would have been caused by damage to the cerebellum. (2 marks) When Daryl fell from his motorcycle he was riding with his friend Barry. Barry saw the accident and immediately stopped riding and ran to his friend to help. Daryl was trapped under his motorcycle in a ditch by the side of the road and despite Daryl and the motorcycle both being heavier than Barry he was able to pull Daryl from under the motorcycle and out of the ditch to perform CPR. Describe the nervous signals that were sent between Barry’s body and brain from the time he witnessed the accident to commencing CPR on his friend. (5 marks) In hospital, doctors suggested using cell replacement therapy to treat Daryl’s damaged cerebellum. What is cell replacement therapy? What is one other disorder that has been treated, (at the clinical trial stage) using this method? (2 marks)",
