    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 41(20 marks) Antibiotics are medications that are used to treat bacterial infections but are not effective against viral pathogens. Outline the reasons why antibiotics are ineffective against viral infections. (3 marks) What is an antibiotic? In your answer name the two different types of antibiotic medications and describe how they work to combat a bacterial infection. (7 marks) Vaccines can be used to provide immunity to a disease without ever becoming infected. Aside from live-attenuated vaccines name two different types of vaccines and describe their features. (4 marks) Rani was vaccinated against measles when she was an infant but her friend Martha was not. They both went on holiday and were contacted later about a measles outbreak on the plane on the way back to Perth. Martha became ill and contracted measles whereas Rani did not. Describe the difference between Rani and Martha’s immune response to the measles pathogen when they were exposed on the plane. (6 marks)",
