    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 31(14 marks) The genetic condition thalassemia is caused by a mutation that occurs in roughly 3% of the global population. It has been found that there are two main types of thalassemia: alpha thalassemia and beta thalassemia. (a) (i) Define the term mutation.(1 mark) (ii) Two main types of mutations are somatic and germ line. Explain which type of mutation thalassemia is. (2 marks) (b) Name a population typically affected by thalassemia.(1 mark) (c) State three symptoms people with the intermediate form of alpha thalassemia and beta thalassemia would have in common.(3 marks) (d) Thalassemia is a condition that provides a heterozygote advantage to malaria. (i) What is the term given to how malaria is transferred?(1 mark) (ii) Explain the term heterozygote advantage using the example of thalassemia.(2 marks) (iii) Name one other condition that provides a similar advantage to malaria. (1 mark) (e) People who suffer repeated infection by malaria show reduced symptoms with each subsequent infection, which is commonly referred to as “seasoning.” Explain how seasoning would reduce the symptoms shown by people with repeated infections by malaria.(3 marks)",
