    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 32(20 marks) Since the beginning of January until the end of March, an outbreak of coronavirus (COVID-19) saw more than 700,000 infected and more than 33,000 die from the disease globally. Originating in Wuhan city in China, the coronavirus was believed to have first infected people in a seafood wholesale market, causing sufferers to experience breathing difficulties, fever, coughing and shortness of breath. Current estimates are that the incubation period is up to 14 days, with most asymptomatic (showing no symptoms) until 5-6 days after infection. (a) A person with coronavirus experiences most symptoms in their respiratory system. Describe the external defence mechanisms of the respiratory system and suggest how they are believed to assist the body to defend itself against disease.(6 marks) (b) (i)Given a person is asymptomatic for up to 5-6 days after infection, explain how this could have affected the incidence of the disease.(2 marks) (ii) What measures could an individual put in place in order to reduce their chance of catching the disease?(2 marks) (iii) A number of mechanisms were put into place by governments as a result of the increasing numbers of infections. China restricted all movements in or out of Wuhan, cruise liners held their passengers on board in their rooms and people who had travelled internationally were asked to not attend school or work for 14 days after their return home. Explain how it is believed these measures will affect the number of people with the disease.(2 marks) (c) Researchers in Queensland have been working on a vaccine for the coronavirus since its outbreak. (i) Why could this not be a toxoid vaccine?(1 mark) (ii) Explain why a sub-unit vaccine could be used as a potential vaccine against coronavirus.(3 marks) (iii) What type of immunity would be provided by a vaccine against coronavirus? (2 marks) (iv) State one economic and one sociocultural reason why some people may not want their child vaccinated against coronavirus.(2 marks)",
