    "title": "2020 Human Biology Units 3 & 4 · Q33",
    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 33 (32 marks) A fossil specimen of a young woman was found in a cave in China that showed characteristics of both Neanderthals and Denisovans (another fossil group). A small amount of DNA was retrieved from her bones and analysed using DNA electrophoresis. (a) Describe the conditions required for the young woman to be fossilised.(4 marks) (b) Name the process that would have multiplied the amount of DNA found in her bones and briefly explain what would occur in each stage.(7 marks) (c) DNA electrophoresis was conducted in order to compare her DNA to a sample of pure Neanderthal DNA and a sample of pure Denisovan DNA from other sites. (i) What would all three DNA samples have been treated with prior to being placed in the agarose gel? (1 mark) (ii) Explain why and how the DNA moves across the gel during the electrophoresis process.(3 marks) The results of the DNA electrophoresis are shown below: Young woman Neanderthal Denisovan (iii)Draw an arrow in the box on the diagram above to show the direction that DNA would move during the process of gel electrophoresis.(1 mark) (iv)Draw a circle around one lane of DNA on the image above.(1 mark) (v) Explain what the results on the agarose gel shows about the young woman.(2 marks) (d) These three specimens as well as Homo sapiens were studied in order to determine the evolutionary relationships between the specimens. The table below shows a portion of the amino acid sequence for the same gene from each specimen. Table 1: Amino acid sequence for one gene Amino acid sequence in one gene Young woman ile trp cys his Neanderthal glu val iso ser Denisovan ile asn ala his Homo sapiens ile trp cys phe (i) Name one gene on which this comparison could have been made.(1 mark) (ii) According to the table of amino acid sequence data above, who is most closely related to the young woman?(1 mark) (iii) The scientists also studied the DNA of this amino acid sequence. Would comparative DNA or comparative proteins provide more accurate data about their relationship? Justify your answer.(2 marks) (iv) Construct a phylogenetic tree using the amino acid sequence data in the table above. (3 marks) (e) Describe the differences between aspects of the culture and tools associated with Neanderthals and Homo erectus.(6 marks)",
