    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 35 (22 marks) In 2001, Pat Rafter suffered from extreme cramps and lost the semi-final in the Australian Tennis Open to Andre Agassi. After testing, it was found Rafter sweats twice as much as other people in the same conditions. (a) (i)What hormone, produced by the hypothalamus, would be released as a result of the volume of sweat lost?(1 mark) (ii)Describe and explain the effect of this hormone on its target cells.(2 marks) (b) (i)Pat Rafter was initially told to drink more water during his tennis matches in order to prevent dehydration. Explain why drinking more water would have made his problem worse. (3 marks) (ii) Name the hormone that would be produced after consuming large amounts of water and state one behavioural mechanism Pat Rafter could take in order to minimise the effect of his heavy sweating.(2 marks) (c)A graph of Pat Rafter’s fluid concentration during normal activity is shown below. (i)What type of feedback model is shown in the graph above? (1 mark) (ii)During normal activity, Pat Rafter stays between the lines marked A on the graph. What do these lines represent?(1 mark) (iii)What does the line marked B on the graph represent?(1 mark) (d)Thermoregulation relies on both hormonal and nervous control. Describe how temperature can be regulated using both hormonal and nervous controls. (6 marks) (e) The scientists investigating Pat Rafter’s problem chose three other tennis players to compare Pat against. Pat and the other players were weighed before and after their games in one tournament. Games were timed so that they could calculate the water loss per hour. The tournament ran over 5 days and the players had varying levels of success, with one making it to the grand-final. (i)Name one variable the scientists controlled. (1 mark) (ii)Name one potentially uncontrolled variable and explain the effect of this on the experiment.(2 marks) A lab assistant was asked to create the table of results for the experiment, which is shown below. Title: Weight loss Body weight Subject Before game After game Average 1 2 3 4 (iii) Identify two (2) errors the lab assistant has made in constructing the table. (2 marks) End of Section Two Section Three: Extended answer 20% (40 Marks) This section contains four (4) questions. Questions 36 and 37 are from Unit 3. Questions 38 and 39 are from Unit 4. Answer one (1) question from Unit 3 and one (1) from Unit 4. Use a black or blue pen for this section. Only graphs and diagrams may be drawn in pencil. Responses can include: labelled diagram with explanatory notes; lists of points with linking sentences; labelled tables and/or graphs; and/or annotated flow diagrams with introductory notes. Supplementary pages for the use of planning/continuing an answer to a question have been provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 50 minutes Unit 3 Choose either Question 36 or Question 37. Indicate the question you will answer by ticking the box next to the question. Write your answer on the pages provided.",
