    "title": "2021 Human Biology Unit 3 · Q32",
    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 32 (17 marks) Scientists wanted to test the hypothesis that neurotransmitters released from a specific group of nerve cells (called the NTS) found within the medulla oblongata, increases long term memory retention in humans. The NTS are ascending tracts that link to the amygdala, which is a part of the brain responsible for emotional memories. To investigate this theory, scientists exposed two rats to inhibitory avoidance training. To do this experiment, each rat was tested separately. They were placed into a box, facing a closed sliding door. The box was well lit with white light. Once the rat turned away from the door, the door was opened, allowing free access to a darker, secluded box. The moment the rat turned to face the open door, a timer was started and once the rat had completely entered the dark room, the door was closed and the time was stopped and recorded. Upon entering the dark room, a footshock (weak electrical current passed into the rat’s foot via the floor) was administered. Immediately after the footshock, the rat was removed from the dark box and given a dose of lignocaine into the NTS. Lignocaine is an anaesthetic that binds to sodium-gated channels and prevents them from opening. Memory for the footshock training is assessed by retesting the rat from 24 to 96 hours later. In this test, the rat is placed in the well-lit box as before, the door is opened once the rat looks away and the time taken for the rat to enter the dark box where the footshock was received earlier is recorded. The time recorded is used as an indicator of the level of memory retention. The results from the experiment can be seen below. Time passed since rat given lignocaine (hours) Time passed before rat entered dark room (seconds) Rat not given lignocaine Rat given lignocaine 12 180 181 24 150 152 36 135 132 48 138 130 60 152 130 72 220 125 84 260 120 96 300 118 Identify the Independent variable Dependent variable (2 marks) State why the scientist provided a rat with inhibitory avoidance training, but did not administer lignocaine. (2 marks) Plot a graph of the information contained in the table. (A spare graph has been provided on page 33 if required). (6 marks) What conclusions can be drawn from the results? (2 marks) Name the process that would have been inactivated by the lignocaine in the NTS and explain why the post-synaptic knobs in the amygdala would not have been stimulated. (5 marks)",
    "source": "2021 Human Biology Unit 3",
