    "searchText": "Question 34 (13 marks) Nicole is highly allergic to shellfish and if she accidentally consumes any product with shellfish in it, she can go into anaphylactic shock. Symptoms of anaphylaxis include a red and hot rash, throat or tongue swelling, difficulty breathing, vomiting and low blood pressure. In the event she does go into anaphylactic shock, she carries an EpiPen®, which can provide her with a dose of epinephrine (adrenaline) and alleviate the symptoms. Name the protective reflex that occurs as a result of the anaphylactic shock and describe how it occurs. (2 marks) Describe how the adrenaline would make breathing easier. (1 mark) Adrenaline is classified as an amine hormone. Explain how this hormone acts on a cell and causes the cell to produce a particular protein. (3 marks) An adult EpiPen® typically injects 0.3mg of adrenaline. If the device was to inject anymore, it would not have any further effect. Explain why. (3 marks) Complete the following table to distinguish between the specific effects of the parasympathetic and sympathetic divisions. Parasympathetic Sympathetic Specific effect on the digestive system Specific effect on the bladder (4 marks)",
