    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 36 (15 marks) A freestyle diver is someone who swims under water without any breathing apparatus, to the deepest possible depth, before returning to the surface. In an effort to stay under water for as long as possible, they will hyperventilate. The danger of this sport is that the diver could lose consciousness and drown. This consequence is referred to as “blacking out”. The two graphs below show the relationship between the levels of oxygen and carbon dioxide within a freestyle diver’s bloodstream. One of the graphs shows what happens to the gas levels without hyperventilating. The other shows what happens to the gas levels when the diver hyperventilates before diving. Study these two graphs and answer the questions that follow. Graph 1 Graph 2 State which of the two graphs shows what happens to the gas levels when the diver has hyperventilated. Explain your answer. (2 marks) Looking at the points indicated by the letters A, B and C on the graphs above, state how the diver’s body is responding and what the diver is doing (3 marks) One of the graphs above shows where the diver has reached the surface and taken a breath. Circle and clearly label this area on the relevant graph above, using the letter D.(1 mark) Hyperventilating can be brought on through physical stress. To help someone recover from hyperventilation, they can breathe into and out of a paper bag a number of times. Explain why this technique prevents someone from losing consciousness and allows them to regain control over their breathing rate. (5 marks) Hyperventilation can lead to respiratory alkalosis. This disorder can bring about a decrease in potassium and calcium levels within the bloodstream, which then leads to uncontrollable muscle cramping. Complete the following table to summarise how the endocrine system would respond to the decrease in potassium and calcium. Gland Hormone name Hormone level raised or decreased? Target organ/s Main effects Increases level of calcium in the blood Decreases removal of potassium from the blood (4 marks)",
