    "searchText": "Question 37 (14 marks) Complete the diagram below of a reflex arc, by drawing in and clearly labelling the missing structures/components. The neuron leading to the effector has already been drawn for you.(3 marks) (Skeletal muscle) (Skeletal muscle) To make it easier to describe the various functions of the peripheral nervous system, it has been classified into divisions and subdivisions. Complete the following table to classify and describe the neural pathway shown in the diagram on the previous page. Division(s) Description of division(s) Subdivision(s) Description of subdivision(s) Name of neurotransmitter(s) released (5 marks) Below is an action potential graph, showing the outcome from two different stimuli on the same neuron. The first stimulus resulted in Line 1 and the second stimulus results in Line 2, as shown on the diagram on the previous page. Describe what occurred to result in Line 2 and state one reason why this has happened. (2 marks) Describe the events occurring at the sections labelled A and C. Section A Section C (4 marks) Section Three: Extended answer 20% (40 Marks) This section contains three (3) questions. You must answer two (2) questions. Make sure you clearly indicate which question you are answering and write your answers in the space provided. Spare pages are included at the end of this booklet. They can be used for planning your responses and/or as additional space if required to continue an answer. Planning: If you use the spare pages for planning, indicate this clearly at the top of the page. Continuing an answer: If you need to use more space to continue an answer, indicate in the original answer space where the answer is continued, i.e. give the page number. Write the number of the question(s) that you are continuing to answer at the top of the additional space page. Responses could include clearly labelled diagrams with explanatory notes; lists of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Suggested working time: 40 minutes.",
