    "searchText": "Question 38 (20 marks) Tuberculosis is a disease caused by a bacterium which invades and replicates inside the cells of their host. Subsequently, the body responds by disrupting the intracellular phase of the bacterial infection. State the name of the specific immune response that would be triggered for this type of bacteria and explain the events that would occur to eradicate the disease in the short term and prevent its return in the future. (10 marks) Jacinta travels from Australia to Siberia for a three-week skiing holiday and chance to see Lake Baikal, the world’s deepest lake. Even though she was aware and well prepared for the difference in climate, Jacinta really notices the cold whenever she is outside. Name and describe the role of two hormones that would be released to regulate Jacinta’s body temperature during her stay in Siberia. Include in your answer, how the release of these hormones are controlled. (6 marks) Outline two behavioural responses that will be useful to employ and describe how these responses will help her stay warm. (4 marks)",
