    "searchText": "6.The central nervous system is believed to use approximately 20% of all the body’s energy. Below is a list of events that occur during the transmission of a nerve impulse across a synapse. i) reuptake of acetylcholine ii) production of neurotransmitters iii)diffusion of neurotransmitters iv) exocytosis v)neurotransmitter connects with receptors Which of these events would require energy? (a)ii), iii) and v) only (b)ii), iv) and v) only (c)i), ii) and iv) only (d)i), ii) and iii) only",
