    "originalStem": "The central nervous system is believed to use approximately 20% of all the body’s energy. Below is a list of events that occur during the transmission of a nerve impulse across a synapse. i) reuptake of acetylcholine ii) production of neurotransmitters iii)diffusion of neurotransmitters iv) exocytosis v)neurotransmitter connects with receptors Which of these events would require energy?"
