    "searchText": "Question 31(15 marks) An AFL umpire was tested for his level of fitness by running on a treadmill in a laboratory held at 21oC. While running, his breathing rate and heart rate increased and he produced a large volume of sweat. (a) Which part of his brain would have controlled both his breathing and heart rate? (1 mark) (b) His breathing rate increased during the fitness test. (i)Name the product of cellular respiration that would have caused this change in breathing rate.(1 mark) (ii) Name the type of receptor that would have detected this stimulus and state where in the body these receptors are found.(2 marks) (iii)State the effectors in his body that would have increased his breathing rate. (2 marks) (c)Account for the large volume of sweat that he produced during his test.(1 mark) (d)During the fitness test it was noticed that the umpire’s core body temperature increased. Name the two main transfer mechanisms that would have allowed him to lose heat during the test and explain how each achieves a lower core body temperature.(8 marks)",
