    "searchText": "Question 32(19 marks) Figure 1 below shows a nerve pathway. Figure 1 (a)The nerve pathway shown above can be considered to be a reflex arc. Use evidence from the image above to indicate why this might be the case.(2 marks) (b)Reflex arcs are known to be the fastest of all neural processes. Why can reflexes occur faster than all other neural processes?(1 mark) (c) Use the characteristics of how the systems function to explain why both nervous and endocrine systems are required in the body.(4 marks) (d) Where would cell body 2 in Figure 1 be found?(1 mark) (e) Explain the role neurotransmitters play in reflex arcs.(2 marks) (f) If the muscle shown in the pathway is a skeletal muscle, which neurotransmitter would be involved in causing it to contract?(1 mark) (g) Explain the changes required for an action potential to occur.(4 marks) (h) A refractory period is part of all action potentials. Define the term refractory period and describe its purpose.(2 marks) (i)Dopamine is a neurotransmitter. Too much dopamine is associated with schizophrenia. One treatment for schizophrenia is to consume a drug that fills dopamine receptors on the post-synaptic membrane. Explain how this drug might help to minimise the symptoms of schizophrenia.(2 marks)",
