    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 33 (22 marks) Since the beginning of January 2020 until the end of February 2021, an outbreak of coronavirus (COVID-19) has seen more than 114 million people infected and more than 2.5 million die from the disease globally. Numerous countries have worked tirelessly on developing a vaccine for the disease and there are currently a number of vaccines that have just recently been made available to the public. Sir Patrick Vallance, the UK’s chief scientific adviser said, “The miracle of the vaccines is extraordinary. We went from having no vaccine at all to having effective vaccines in a period of a year. That has never been done before for any other disease.” The first study in England showed one dose of the Pfizer vaccine slashes the risk of hospitalisation and death by at least 75% among those aged over 80. Researchers looked at more than 12,000 people in this group in England after they were vaccinated to see if they fell ill, had to be admitted to hospital, or died. They were 57% less likely to develop symptomatic infection 28 days after the vaccination with a single dose, which increased to 88% after a second dose. (a)What aspect of the methodology is improved by using more than 12,000 people in the study?(1 mark) (b)The more than 12,000 people who were vaccinated formed one group in the study. (i)What is the name given to this group of people?(1 mark) (ii)Describe the other group of people who would have made up this study. (1 mark) (c)Explain why the elderly were less likely to develop symptomatic infection after the second dose of the Pfizer vaccine than they were after the first.(2 marks) (d)Vaccines are usually tested extensively on animals prior to them being used in human trials. Describe the key ethical points researchers would have to be aware of prior to any animal testing taking place.(3 marks) (e)There are concerns in the community that people could develop COVID-19 as a result of them having been given the vaccine. With reference to sub-unit vaccines, explain why this is not a possibility. (3 marks) (f)Some people have attended an anti-vaccine rally in Australia’s capital cities protesting against taking the vaccine. Give three reasons, other than thinking they may “catch” the disease from the vaccine, why people may not want to take the vaccine.(3 marks) (g)What type of immunity is offered by the vaccine?(2 marks) At the same time, another disease, Buruli ulcer disease, appeared in and around Melbourne. A type of flesh-eating disease caused by a bacterium, Buruli ulcer disease has seen a large increase in incidence in the last few years. Studies show that the bacterium that causes the disease is also found in possums and mosquitoes. (h)State three ways in which viruses and bacteria are different.(3 marks) (i)Mosquitoes are believed to be the vector for this disease. What does this mean? (1 mark) (j)Unlike COVID-19, Buruli disease can be treated with antibiotics. Explain how antibiotics affect bacteria.(2 marks)",
