    "searchText": "Question 35 (19 marks) Scientists investigated the effect of the concentration of carbon dioxide in air breathed by firefighters on their blood pH. They asked 5 firefighters to wear a full-face mask that was connected to a gas cylinder of varying carbon dioxide concentrations. During each test, the firefighters were asked to breathe normally and after 2 minutes, a finger prick test was conducted and their blood analysed to determine their blood pH. The scientists gave the firefighters a 1 minute rest between each gas test before commencing the next test. The scientists tested normal air (0.04% carbon dioxide), 0.08% and 0.12%. (a) Write a hypothesis the scientists may have been testing.(2 marks) (b)Identify the dependent variable.(1 mark) (c) Construct a table to show how these results would have been collated.(4 marks) (d)The pH meter the scientists used could be set to give results to one or two decimal places. The scientists chose to receive their data to two decimal places. What have they improved?(1 mark) (e)Explain how the scientists improved the reliability of their investigation.(2 marks) (f)The results in this experiment may not have been valid. Using evidence, explain one factor that may have affected the validity and suggest how the scientists could improve the validity of their experiment.(3 marks) (g) Explain the relationship between carbon dioxide concentration and blood pH.(3 marks) (h)Before firefighters enter burning buildings, they will often unconsciously hyperventilate. Suggest how and why this may affect them.(3 marks)",
