    "searchText": "Question 36 (13 marks) A group of archaeologists in South Africa were working on a series of core samples removed from one site. Their core samples are shown below. 11 22 33 44 55 Core A Core B (a)(i)Fossils were found in Core A layers 4 and 5 and it was determined that the fossils found in layer 5 were older than those found in layer 4. State the dating method used to date these fossils.(1 mark) (ii)Discuss two limitations of this method.(2 marks) (b)Charles Darwin compared the fossil record to a book, a book with some pages and some words on each page missing. Explain why the fossil record may not be complete.(3 marks) Mitochondrial DNA was extracted from the fossils taken from the two layers. (c)Explain why mitochondrial DNA is more commonly used than nuclear DNA in investigations like these.(2 marks) DNA sequencing of a gene from both sets of mitochondrial DNA was conducted in order to compare them. (d) The DNA from the two fossils (fossil 1 and fossil 2) as well as two potential close relatives (relative 3 and relative 4) were studied in order to determine the evolutionary relationships between the specimens. The table below shows a portion of the DNA sequence for the same gene from each specimen. Table 1: DNA sequence for portion of one gene DNA sequence in portion of one gene Fossil 1 A A C G T T G A Fossil 2 A A C C T T A A Relative 3 A A T T T A A C Relative 4 A C G A C G C T (i) Name one gene on which this comparison could have been made.(1 mark) (ii) According to the table of DNA sequence data above, who is most closely related to fossil 1?(1 mark) (iii) Construct a phylogenetic tree using the DNA sequence data in the table above. (3 marks) End of Section Two Section Three: Extended answer 20% (40 Marks) This section contains four questions. You must answer two questions. Questions 37 and 38 are from Unit 3. Questions 39 and 40 are from Unit 4. Answer one question from Unit 3 and one question from Unit 4. Responses could include clearly labelled diagrams with explanatory notes; lists of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Supplementary pages for planning/continuing your answers to questions are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 50 minutes Unit 3 Choose either Question 37 or Question 38. Indicate the question you will answer by ticking the box next to the question. Write your answer on pages 28-32. When you have answered your first question, turn to page 33 and indicate on that page the second question you will answer.",
