    "searchText": "Question 31 (19 marks) Athletes training for sports with specific weight divisions like boxing and weightlifting participate in ‘cutting weight’ to be placed in the lowest weight category possible. One method used by these athletes is to dehydrate themselves before being weighed to cut as much water weight from their body as possible. A long-term effect of dehydration is kidney damage. A researcher wants to investigate the possible long-term consequences on kidney function for athletes who practice ‘cutting weight’. The test that the researcher will use to determine kidney function is the Glomerular Filtration Rate (GFR). Describe a control group that could be used for this study. (2 marks) Suggest a method that the researcher could employ to test the hypothesis. ‘Athletes in their 20’s who practise ‘cutting weight’ have reduced kidney function as measured by the GFR compared to a control group’. (5 marks) The test that the researcher will use to determine kidney function is the Glomerular Filtration Rate (GFR) the results of which are shown in the chart below. Use the chart above to answer the following. (3 marks) What stage of chronic kidney disease would a person be at if their GFR result was 35? What percentage of kidney function would a person have if they were at stage 5 of chronic kidney disease? What percentage of kidney function would a person have if their GFR result was 70? The researcher found the following results. Experimental Group GFR Control Group GFR Participant 1 90 Participant 1 95 Participant 2 72 Participant 2 92 Participant 3 63 Participant 3 88 Participant 4 80 Participant 4 73 Participant 5 55 Participant 5 97 Use the grid below to construct a line graph for the experimental and control groups. (Spare grid available at back of booklet) (5 marks) Determine the mean GFR for each group. (2 marks) Experimental: Control: State a conclusion that could be made based on the results of this study. (2 marks)",
