    "searchText": "Question 33 (13 marks) Hormones are chemical messengers that cause changes in the body. Describe how hormones are transported to target cells throughout the body. (3 marks) Some hormones occur in antagonistic pairs. This is when hormones have opposite effects on the body. Complete the table below to identify the antagonistic hormones. (4 marks) Hormone Effect on the Body Secreted when blood calcium is high to supress breakdown of the bone matrix. Secreted when blood calcium is low and increases calcium absorption in the intestines. Secreted when blood glucose is low to cause glucose production from glycogen. Secreted when blood glucose is high to cause glycogen production from glucose. Growth hormone deficiency (GHD) is a disorder that is caused by the underproduction of growth hormone in the body. Name the endocrine gland that produces growth hormone. (1 mark) Describe three (3) functions of growth hormone on the body. (3 marks) Suggest two (2) symptoms a person may suffer because of the underproduction of growth hormone if they suffer with GHD. (2 marks)",
