    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 35 (15 marks) The diagram below shows the process of myelination of an axon What is the name of the cell that creates the myelin sheath in the PNS? (1 mark) Guillain-Barré syndrome (GBS) is a rare disorder where the body’s immune system damages the myelin sheath of neurons. The damage to the nerves causes muscle weakness and sometimes paralysis. While its cause is not fully understood, the syndrome often follows infection with a virus and is most often found in people over 50. The cells of the autonomic nervous system are affected which can cause heart-rate irregularities. Identify two (2) functions of the myelin sheath. (2 marks) Explain how damage to the myelin sheath can cause muscle weakness and paralysis. (3 marks) Explain how damage to the autonomic nervous system can cause heart-rate irregularities. (3 marks) Compare and contrast how nervous propagation occurs along myelinated and unmyelinated axons. (6 marks)",
