    "searchText": "Question 37 (11 marks) The lymphatic system has many functions in the body to remove mutated cells, virally infected cells and non-self-antigens from the body Name one cell that removes virally infected cells and describe its function. (2 marks) Name and describe the function of one (1) cell that incapacitates non-self-antigens and removes them from the body. (2 marks) In 2001 there was a series of letters that were sent throughout the US that contained the infectious bacterium anthrax. Describe the series of events the body would go through between being infected with the bacterium anthrax, which invades the hosts blood stream and produces toxins, to recovery. (7 marks) Section Three: Extended answer20% (40 marks) This section contains four questions. You must answer two questions. Answer one question from 38 and 39 and one question from 40 and 41. Responses could include clearly labelled diagrams with explanatory notes; lists of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Supplementary pages for planning/continuing your answers to a question are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time for this section is 40 minutes. Answer one question from Questions 38 to 39. Indicate the questions you will answer by ticking the box next to the question. Write your answers on pages that follow.",
