    "searchText": "Question 31 (20 marks) (a)Complete the table below for each of the following scenarios by placing the letter (A, B, or C) in the correct box to show the type of immunity it demonstrates.(3 marks) ACatching tetanus from a rusty nail BA one month old does not suffer from the cold her mother has CBeing given an injection after being bitten by a snake Type of Immunity Natural Immunity Artificial Immunity Active Immunity Passive Immunity (b)Genes isolated from DNA can be used in gene therapy to treat conditions like cystic fibrosis. Healthy individuals have a gene that codes for a channel protein found in the cell membrane of many body cells, including those lining the trachea. People suffering from cystic fibrosis do not have a functioning gene, so their cells do not form these channel proteins. (i)The treatment of cystic fibrosis is described as a somatic gene therapy. Another type of gene therapy is known as a germ-line therapy. State two differences between somatic gene therapy and germ-line therapy.(4 marks) (ii)A student suggested his elderly grandmother, who suffers from Alzheimer’s, could be treated with gene therapy. His friend suggested she should be treated with cell replacement therapy. Explain who is correct.(3 marks) (c)Two children were given an injection. They were then tested each day to determine the levels of antibodies in their blood. Their results are shown below. Time (days) Levels of antibodies in the blood (kAU) Child 1 Child 2 0 5 5 1 20 190 3 100 170 5 150 130 9 90 30 14 60 10 15 50 3 (i)Graph this data to show how the antibody level changed over time for each child. (A spare grid can be found at the end of this booklet).(5 marks) (ii)What was contained in the injection given to Child 2?(1 mark) (iii)Explain the immunological response of Child 1 if they came into contact with the same antigen that caused this response, in the future.(2 marks) (iv)State two ways in which antibodies can act against an antigen.(2 marks)",
