    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 32(16 marks) People who suffer from Type I and Type II diabetes are encouraged to consume food with a low glycaemic index (GI). The glycaemic index rates food from 0 to 100, indicating how quickly it increases blood glucose concentrations. To determine the GI of a biscuit, scientists asked 5 people to fast overnight. The next morning, each person consumed one biscuit and blood samples were taken every 15 minutes for 2 hours in order to determine their blood glucose concentration. The mean value of all subjects was used to determine the GI for that food. (a)Why were all subjects asked to fast overnight?(2 marks) (b)For the GI calculation to be valid, a number of variables must be controlled. Suggest two variables that must have been controlled.(2 marks) (c)The mean value of all subjects was used to calculate the GI of the biscuit. Explain why the mean value for all subjects was used and suggest one limitation of this method. (2 marks) (d)How could the determination of the GI of the biscuit be made more reliable? (1 mark) Older people can develop a condition called Type II diabetes, where they have high blood glucose levels, even though they produce normal amounts of insulin. (e)Explain why these people have high blood glucose levels, even though they may produce normal amounts of insulin.(1 mark) (f)Suggest two symptoms a person would experience if they suffered from Type II diabetes.(2 marks) (g)Suggest two changes a person suffering from Type II diabetes could make in order to better manage their blood glucose levels.(2 marks) (h)Insulin targets the liver. What other main tissue type does insulin target?(1 mark) (i)Name the process that occurs in the liver as a result of insulin being present.(1 mark) (j)State the effect of adrenalin on blood glucose levels and explain why this is required at times.(2 marks)",
