    "searchText": "Question 35 (17 marks) Recently, a mining giant funded an archaeological excavation at the Yirra rock shelter near Paraburdoo in the Pilbara of Western Australia, where they retrieved stone tools, charcoal and bone. Six individuals were identified, 4 adults and 2 children. The fossils were dated at 50,000 years. Mitochondrial DNA testing determined that three of the adults and both children were related to each other. (a)Explain how these specimens could have been dated.(5 marks) (b)Mitochondrial DNA was used to determine the relatedness of the individuals found in the rock shelter. Explain one advantage and one disadvantage of using mitochondrial DNA rather than nuclear DNA.(3 marks) (c)At another site in Europe, scientists determined their specimens belonged to Homo neanderthalensis. State one anatomical and two cultural differences that existed between Homo neanderthalensis and Homo sapiens (Cro magnon).(6 marks) Homo neanderthalensis Homo sapiens (Cro Magnon) Anatomical Cultural (d)Two tools, excavated from different archaeological sites, were compared. Tool A was found attached to a portion of a stick while Tool B was not. (These images are not to scale). Tool ATool B (i)What is the method of attaching tools to wood called?(1 mark) (ii)Which hominin would have produced Tool B?(1 mark) (iii)Which tool, Tool A or Tool B, would have been produced first?(1 mark)",
