    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 38 (20 marks) Vaccines were first developed by Edward Jenner in 1796 when he observed that milk maids who milked cows suffered from a mild cowpox but did not suffer from the severe smallpox disease. In order to protect a young boy from the dangerous smallpox disease, Jenner scratched the boy’s skin with the mild cowpox disease. (a)Compare and contrast the different types of attenuated vaccines and give an example of each type.(8 marks) (b)The formation of subunit vaccines requires the use of recombinant DNA technology. Describe in detail how a subunit vaccine could be produced and briefly explain why it is not possible for people receiving a subunit vaccine to actually suffer from the disease due to the vaccination itself.(12 marks)",
