    "searchText": "Question 33(12 marks) Lyme disease is a bacterial borne disease that is transmitted to humans by a bite from an infected tick. (a)Identify the mode of transmission for the bacteria that causes Lyme disease.(1 mark) (b)State three structural features of a bacterium.(3 marks) One: Two: Three: Lyme disease, caught early, is usually treatable through a course of broad spectrum, bacteriostatic antibiotics such as amoxicillin. (c)Describe what is meant by broad spectrum, bacteriostatic antibiotics.(2 marks) If left untreated, Lyme disease could potentially lead to peripheral nerve dysfunction due to damage around the spinal cord. This can result in a loss of sensation in some areas of the body. The diagram below shows the structure of the spinal cord. (d)Name and contrast the structure of the sections labelled C and D in the diagram. (3 marks) (e)Identify which part in the diagram, A or B, would be damaged if someone had a loss of sensation. Explain your answer.(3 marks)",
