    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 34(25 marks) An investigation to determine the effect of thyroxine (T4) on core body temperature was carried out on mice. Twenty mice were split into two groups of ten, one group was given periodic injections of T4 over 12 days, while the other group acted as a control. The internal temperature of each mouse was taken every two days over a 12 day period. The average core temperature for each group over the time period is shown in the table below. Table 1. Average core temperature for mice with and without T4 injections over 12 days Average core temperature (°C) Days Group One (given injections of T4) Group Two (control group) 0 37.2 37.0 2 37.2 37.1 4 37.6 36.8 6 38.0 37.2 8 38.2 37.4 10 38.6 37.5 12 39.0 37.4 (a)Identify the dependent variable in this investigation.(1 mark) (b)Explain the role of the control group.(2 marks) (c)Suggest two controlled variables for this experiment.(2 marks) (d)Construct a graph of the data in Table 1 on the grid below.(5 marks) A spare grid is provided at the end of this Question/Answer Booklet. If you need to use it, cross out this attempt and indicate that you have redrawn it on the spare grid. (e)Explain the trend shown in this data using scientific reasoning.(4 marks) The findings from this investigation could be used as important data to help further understand the condition known as hyperthyroidism, which can be displayed through symptoms such as excessive sweating and intolerance to heat. (f)Describe what is meant by hyperthyroidism and suggest one possible cause of this condition in humans(2 marks) (g)Explain how hyperthyroidism could lead to excessive sweating.(4 marks) (h)Explain how excessive sweating could lead to the initiation of the thirst reflex, and describe this homeostatic response.(5 marks)",
