    "searchText": "Question 35(15 marks) The speed of the nerve impulse along myelinated nerve fibres averages around 80 – 120 m/s, whereas the average speed along unmyelinated fibres ranges from 0.5 – 2.0 m/s. (a)Name the cells of the peripheral nervous system that form the myelin sheath.(1 mark) (b)Describe how an action potential is generated along a nerve fibre.(5 marks) (c)Explain why the speed of propagation of an action potential is faster along a myelinated fibre.(3 marks) Guillain-Barre syndrome is an autoimmune condition that leads to the destruction of the cells that form myelin in the peripheral nervous system. Symptoms can range from skeletal muscle weakness to damage to the autonomic nervous system, affecting heart rate and kidney function. (d)Name the affected subdivision of the PNS that could have led to skeletal muscle weakness and contrast this subdivision with the autonomic nervous system.(4 marks) (e)The speed of an impulse, even along unmyelinated fibres, is much faster than the speed at which hormones travel in the bloodstream. Outline two other differences between the endocrine and nervous system.(2 marks) One: Two:",
