    "title": "2023 Human Biology Unit 3 · Q36",
    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 36(15 marks) In certain areas of the world, including some mountainous regions of Canada, a job known as an ‘avalanche forecaster’ exists. The role requires skills in mountaineering, knowledge of mountain conditions and dealing with extreme cold weather. In Quebec, where the Laurentian mountain range exists, the average high temperature in January is around – 8 °C and the low temperature is around – 18 °C. (a)Calculate the percentage decrease from the average high to low in January in Quebec. (3 marks) (b)Identify the area of the central nervous system that would be involved in regulating the internal temperature of someone working in these extreme conditions.(1 mark) (c)Describe two physiological responses initiated by the nervous system in response to the cold external temperature experienced in Quebec.(4 marks) One: Two: (d)Identify and explain one behavioural response of someone working as an avalanche forecaster in extremely cold conditions.(2 marks) When working outdoors, the job of an avalanche forecaster could involve a lot of risk, leading to the body to undergo a ‘fight or flight’ response. (e)State the subdivision of the peripheral nervous system that would be stimulated during the fight or flight response.(1 mark) The diagram below shows the cross-section of an endocrine organ that could also be stimulated during the fight or flight response. (g)Identify and name the area of the gland above (either A or B) that would be stimulated in the fight or flight response.(2 marks) (f)Describe and explain the importance of one physiological response initiated by the fight or flight response.(2 marks) End of Section Two Section Three: Extended answer20% (40 Marks) This section has four questions. You must answer two questions. Questions 37 and 38 are from Part A. Questions 39 and 40 are from Part B. Answer one question from Part A and one question from Part B. Responses could include clearly labelled diagrams with explanatory notes; list of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Supplementary pages for planning/continuing your answers to questions are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 50 minutes. Part A Choose either Question 37 or Question 38. Indicate the question you will answer by ticking the box next to the question. Write your answer on pages 28 – 32. When you have answered your first question, turn to page 33 and indicate on that page the second question you will answer.",
