    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "30.On a small, isolated island in the Atlantic Ocean, the inhabitants had never been exposed to measles. When the island was first visited by European explorers, nearly half the population died of measles, while none of the Europeans died. A second wave of measles affected the island population about 10 years later. This time, only 8% of the population died. Since then, there have been no deaths from measles. Which of the following statements is incorrect? (a)The islanders showed a primary response in the first wave of infection. (b)The Europeans had memory cells for measles when they reached the island. (c)Any islanders who caught measles in the second wave would not have had memory cells for measles. (d)The symptoms of measles would have been less severe in those infected again in the second wave of infection. End of Section One Section Two: Short answer 50% (106 Marks) This section has seven questions. Answer all questions. Write your answers in the spaces provided. Supplementary pages for planning/continuing your answers to questions are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 90 minutes.",
