    "searchText": "Question 34 (9 marks) Gel electrophoresis is often used to identify different lengths of DNA. In the same way, it can also be used to identify the different amino acids that form parts of a protein, as the different amino acids have different lengths. (a)At which electrode would you find the longest amino acid chains on an agarose gel? (1 mark) (b)The amino acid sequence of cytochrome C was studied in this way in order to determine the degree of relationship between different species. What is the term given to proteins like cytochrome C that are found in many species?(1 mark) The same portion of cytochrome C protein of four different species was placed on an agarose gel and the results are tabulated below. Species Amino acid A Amino acid B Amino acid C Amino acid D 1 Ala Gly Arg Lys 2 Arg Val Pro Lys 3 Ala Gly Lys Lys 4 Pro Gly Arg Asn (c)Which two species are most closely related?(1 mark) (d)A student created a phylogenetic tree based on this data, which is shown below. Explain whether this phylogenetic tree is correct.(2 marks) (e)Further study indicated that a mutation had occurred in Species 4. The DNA codon of amino acid D that generated Lys was AAG while the amino acid Asn is determined by the codon AAT. Classify this type of mutation. (1 mark) (f)Name two mutagens and explain the effect of any mutagen.(3 marks)",
