    "searchText": "Question 36 (20 marks) Lee and Vinuesa observed the rapid rise in autoimmune diseases such as lupus, diabetes, multiple sclerosis and inflammatory bowel disease over the last 40 years and decided to study the DNA sequence of people suffering from these conditions. They indicated that where once half a dozen DNA variants were known to trigger inflammatory bowel disease, now, due to bioinformatics, over 250 variants are known. (a)Define bioinformatics and explain how it would have contributed to the knowledge base about autoimmune diseases.(2 marks) (b)PCR was a crucial part of Lee and Vinuesa’s study. Give a reason why PCR was required and explain what substances are needed in order for it to be conducted.(5 marks) (c)Differentiate between Type I and Type II diabetes.(4 marks) (d)Untreated diabetes can result in neuropathy in the extremities, where inflammation and damage to sensory neurons result in pain. Name the receptors capable of detecting pain and state the main way in which they are different to all other types of receptors. (2 marks) (e)Multiple sclerosis results in the destruction of myelin. Explain how an action potential would normally be transmitted through a myelinated neuron.(7 marks)",
