    "stem": "Original exam question with its diagrams and tables. Answer each part below.",
    "searchText": "Question 37 (15 marks) The individual shown in the two images above was dated at approximately 2 million years of age. (a)Name this species.(1 mark) (b)(i)State the anatomical feature this individual has that is not shared by any other hominin.(1 mark) (ii)Explain how this feature would have become more common in this population over time.(7 marks) (c)Homo sapiens has been found throughout the world but is believed to have originated in Africa. (i)State the anatomical structure present in this species that is not present in any other hominin and suggest the advantage of having such a structure. (2 marks) (ii)State two different cultural aspects of Homo sapiens (Cro magnon) that set it apart from other hominins.(2 marks) (iii) This tool was found with a Homo sapiens (Cro magnon) specimen in a cave in France. State the tool culture this tool would have been classified as and give one use of such a tool. (2 marks) End of Section Two Section Three: Extended answer 20% (40 Marks) This section contains four questions. You must answer two questions. Questions 38 and 39 are from Unit 3. Questions 40 and 41 are from Unit 4. Answer one question from Unit 3 and one question from Unit 4. Responses could include clearly labelled diagrams with explanatory notes; lists of points with linking sentences; clearly labelled tables and graphs; and annotated flow diagrams with introductory notes. Supplementary pages for planning/continuing your answers to questions are provided at the end of this Question/Answer booklet. If you use these pages to continue an answer, indicate at the original answer where the answer is continued, i.e. give the page number. Suggested working time: 50 minutes Unit 3 Choose either Question 38 or Question 39. Indicate the question you will answer by ticking the box next to the question. Write your answer on pages 28-32. When you have answered your first question, turn to page 33 and indicate on that page the second question you will answer.",
